package de.tum.cit.aet.artemis.atlas.dto;

import org.jspecify.annotations.Nullable;

import com.fasterxml.jackson.annotation.JsonInclude;

import de.tum.cit.aet.artemis.atlas.domain.competency.CompetencyExerciseLink;
import io.swagger.v3.oas.annotations.media.Schema;

/**
 * An exercise linked to a course competency.
 *
 * @param weight        how much the exercise contributes to mastery
 * @param generatedByAi whether the link was generated by AI
 * @param exercise      the linked exercise, when available
 */
@JsonInclude(JsonInclude.Include.NON_EMPTY)
public record CompetencyExerciseLinkResponseDTO(@Schema(requiredMode = Schema.RequiredMode.REQUIRED) double weight,
        @Schema(requiredMode = Schema.RequiredMode.REQUIRED) boolean generatedByAi, @Nullable ExerciseForCompetencyDTO exercise) {

    @Nullable
    public static CompetencyExerciseLinkResponseDTO of(@Nullable CompetencyExerciseLink link) {
        if (link == null) {
            return null;
        }
        return new CompetencyExerciseLinkResponseDTO(link.getWeight(), link.isGeneratedByAi(), ExerciseForCompetencyDTO.of(link.getExercise()));
    }
}
